617	                    const error = field.parentElement.querySelector('.field-error');
618	                    if (!field.checkValidity() && field.value) {
619	                        if (error) {
620	                            error.classList.add('show');
621	                            if (field.type === 'email') {
622	                                error.textContent = 'Please enter a valid email address';
623	                            } else {
624	                                error.textContent = 'This field is required';
625	                            }
626	                        }
627	                        return false;
628	                    } else if (error) {
629	                        error.classList.remove('show');
630	                    }
631	                    return true;
632	                };
633	
634	                const inputs = contactForm.querySelectorAll('input, textarea');
635	                inputs.forEach(input => {
636	                    input.addEventListener('blur', () => validateField(input));
637	                    input.addEventListener('change', () => validateField(input));
638	                });
639	
640	                contactForm.addEventListener('submit', function(e) {
641	                    e.preventDefault();
642	                    let isValid = true;
643	                    inputs.forEach(input => {
644	                        if (!validateField(input)) isValid = false;
645	                    });
646	
647	                    if (!isValid) return;
648	
649	                    const submitBtn = document.getElementById('submit-btn');
