contactForm.addEventListener('submit', function(e) {
    e.preventDefault();
    let isValid = true;
    const feedback = document.getElementById('form-feedback');
    feedback.className = 'form-feedback';

    inputs.forEach(input => {
        if (!validateField(input)) isValid = false;
    });

    if (!isValid) {
        feedback.className = 'form-feedback error';
        feedback.textContent = 'Please correct the errors above and try again.';
        feedback.focus();
        return;
    }

    const submitBtn = document.getElementById('submit-btn');
    submitBtn.disabled = true;
    const originalHTML = submitBtn.innerHTML;
    submitBtn.innerHTML = '<span class="spinner" aria-hidden="true"></span>Sending...';

    setTimeout(() => {
        submitBtn.disabled = false;
        submitBtn.innerHTML = originalHTML;
        feedback.className = 'form-feedback success';
        feedback.textContent = 'Thank you for your message! We\'ll be in touch soon.';
        contactForm.reset();
        inputs.forEach(input => {
            const error = input.parentElement.querySelector('.field-error');
            if (error) error.classList.remove('show');
        });
        feedback.focus();
    }, 1000);
});

